INSERT INTO lab_brands (id, name, short_name, logo, tagline, rating, review_count, is_nabl_accredited, is_cap_accredited, is_iso_certified, total_centers_north_india, home_collection_speed, description, badge, primary_color) VALUES
('lab-agilus', 'Agilus Diagnostics', 'Agilus', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=200&auto=format&fit=crop&q=80', 'Formerly SRL Diagnostics · National Reference Laboratory', 4.9, 14200, TRUE, TRUE, TRUE, 180, '6:00 AM Fasting Slots · 45 Mins Arrival', 'One of India’s largest diagnostic networks with CAP & NABL accredited national reference labs in Gurugram, Delhi, and Chandigarh.', 'NABL & CAP Certified', '#00558F'),
('lab-drlal', 'Dr. Lal PathLabs', 'Dr Lal', 'https://images.unsplash.com/photo-1581595220892-b0739db3ba8c?w=200&auto=format&fit=crop&q=80', 'India’s Most Trusted Diagnostics Since 1949', 4.8, 28900, TRUE, TRUE, TRUE, 220, '6:00 AM Fasting Slots · 40 Mins Arrival', 'Pioneering diagnostic pathology network with over 75 years of clinical excellence in North India.', 'Gold Standard Pathology', '#E4002B'),
('lab-max', 'Max Lab (Max Healthcare)', 'Max Lab', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=200&auto=format&fit=crop&q=80', 'Hospital-Grade Precision Pathology & Super-Specialty Tests', 4.9, 8900, TRUE, TRUE, TRUE, 85, '6:30 AM Fasting Slots · Hospital Phlebotomists', 'Hospital-backed precision pathology network offering high-end super-specialty biomarkers and rapid fever profiles.', 'Hospital Grade Precision', '#004B87'),
('lab-apollo', 'Apollo Diagnostics', 'Apollo', 'https://images.unsplash.com/photo-1631815589968-fdb09a223b1e?w=200&auto=format&fit=crop&q=80', 'Backed by Apollo Hospitals · 100% Barcoded Safety', 4.8, 12100, TRUE, TRUE, TRUE, 110, '6:30 AM Fasting Slots · 60 Mins Arrival', 'ISO certified clinical laboratory backed by Apollo Hospitals Group, specializing in preventive full-body screenings.', 'Apollo Clinical Care', '#007A33'),
('lab-thyrocare', 'Thyrocare Technologies', 'Thyrocare', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=200&auto=format&fit=crop&q=80', 'World’s Largest Automated Preventive Diagnostic Lab', 4.7, 34000, TRUE, TRUE, TRUE, 140, '6:00 AM Fasting Slots · Pan-India Automated Hubs', 'Pioneers in high-volume automated screening with fully robotic track systems and affordable preventive profiles.', 'Best Value Automated', '#F26522'),
('lab-redcliffe', 'Redcliffe Labs', 'Redcliffe', 'https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?w=200&auto=format&fit=crop&q=80', 'Smart Diagnostic Service · AI-Powered Quality Checks', 4.7, 9800, TRUE, FALSE, TRUE, 95, '6:00 AM Fasting Slots · Smart Temperature Bags', 'Modern, technology-driven diagnostic service with temperature-monitored sample transit and instant digital PDF reports.', 'Fast Home Collection', '#E63946')
INSERT INTO medical_tests (id, code, name, category, sample_type, fasting_required, fasting_hours, turnaround_hours, original_price, discount_price, description, why_needed, ideal_for, gender, age_group, parameters, is_popular, is_smog_related) VALUES
('t-01', 'CBC001', 'Complete Blood Count (CBC) with ESR & Platelets', 'Seasonal & Fever', 'EDTA Whole Blood', FALSE, 0, 6, 450, 299, 'Measures 28 blood parameters including Hemoglobin, Platelets, TLC, DLC, RBC indices, and ESR for infection diagnosis.', 'Essential for detecting dengue thrombocytopenia, acute bacterial/viral infections, anemia, and chronic inflammation.', 'Fever, Fatigue, General Checkup', 'ALL', 'All Age Groups', '{"Hemoglobin", "Total Leukocyte Count (TLC)", "Differential Leukocyte Count (DLC)", "Absolute Neutrophil Count", "Platelet Count", "Mean Platelet Volume (MPV)", "Packed Cell Volume (PCV/Hematocrit)", "RBC Count", "MCV, MCH, MCHC, RDW", "Erythrocyte Sedimentation Rate (ESR)"}', TRUE, FALSE),
('t-02', 'LIP002', 'Lipid Profile - Comprehensive Cardiac Risk Marker', 'Heart & Cardiac', 'Serum (Fasting)', TRUE, 12, 8, 850, 499, 'Analyzes Total Cholesterol, HDL, LDL, VLDL, and Triglycerides to evaluate cardiovascular risk.', 'Crucial for assessing plaque buildup risk and metabolic cardiovascular health.', 'Adults 25+, Chest Heaviness, Heart Risk', 'ALL', 'Adults 20+', '{"Total Cholesterol", "HDL Good Cholesterol", "LDL Bad Cholesterol", "VLDL Cholesterol", "Triglycerides", "Total Cholesterol / HDL Ratio", "LDL / HDL Ratio", "Non-HDL Cholesterol"}', TRUE, FALSE),
('t-03', 'HBA003', 'HbA1c (Glycated Hemoglobin) by HPLC', 'Diabetes & Sugar', 'EDTA Whole Blood', FALSE, 0, 6, 650, 399, 'Measures average blood sugar levels over the past 90 days using NGSP-certified HPLC methodology.', 'Gold standard test for diabetes diagnosis, prediabetes screening, and long-term glycemic control monitoring.', 'Diabetics, Pre-diabetics, Routine Screen', 'ALL', 'Adults 18+', '{"HbA1c (Glycated Hemoglobin)", "Estimated Average Glucose (eAG)", "HPLC Chromatogram Graph"}', TRUE, FALSE),
('t-04', 'THY004', 'Thyroid Profile Total (T3, T4, TSH Ultra-Sensitive)', 'Thyroid & Hormones', 'Serum', FALSE, 0, 8, 550, 349, 'Measures Total Triiodothyronine (T3), Total Thyroxine (T4), and Thyroid Stimulating Hormone (TSH).', 'Diagnoses hypothyroidism, hyperthyroidism, unexplained weight changes, and chronic fatigue.', 'Weight Changes, Hair Fall, Fatigue, Women', 'ALL', 'All Age Groups', '{"Total Triiodothyronine (T3)", "Total Thyroxine (T4)", "Thyroid Stimulating Hormone (TSH Ultra)"}', TRUE, FALSE),
('t-05', 'DEN001', 'Dengue NS1 Antigen & Antibody Duo (NS1 + IgM + IgG) with Platelets', 'Seasonal & Fever', 'Serum & EDTA Blood', FALSE, 0, 4, 1250, 799, 'Combined NS1 ELISA antigen detection for early 1-3 day fever, plus IgM/IgG antibodies and emergency platelet count.', 'Critical for timely dengue confirmation and monitoring platelet drop during acute seasonal outbreaks.', 'Acute High Fever, Body Ache, Rash, Low Platelets', 'ALL', 'All Age Groups', '{"Dengue NS1 Antigen ELISA", "Dengue IgM Antibodies", "Dengue IgG Antibodies", "Rapid Platelet Count", "Peripheral Smear Examination"}', TRUE, FALSE),
('t-06', 'FEV002', 'Acute Fever Comprehensive Panel (Dengue, Malaria, Typhoid, CBC & Urine)', 'Seasonal & Fever', 'Serum, EDTA Blood, Clean Urine', FALSE, 0, 6, 1850, 1199, 'All-in-one fever differential diagnostic battery identifying bacterial vs viral causes.', 'Prevents misdiagnosis and dangerous antibiotic misuse by isolating exact etiology.', 'Unexplained High Fever, Chills, Shivering, Nausea', 'ALL', 'All Age Groups', '{"CBC + ESR (28 Parameters)", "Dengue NS1 Antigen Rapid", "Malaria Antigen (Pv/Pf Rapid)", "Typhidot IgM Rapid", "Widal Slide Agglutination", "Urine Routine & Microscopic"}', TRUE, FALSE),
('t-07', 'TYP003', 'Typhoid Typhidot IgM & Widal Slide Agglutination', 'Seasonal & Fever', 'Serum', FALSE, 0, 8, 650, 399, 'Dual test evaluating early Typhidot IgM antibodies and Salmonella slide agglutination titres.', 'Pinpoints Salmonella enterica serotype typhi infection in persistent step-ladder fever.', 'Step-ladder Fever, Abdominal Cramps, Constipation', 'ALL', 'All Age Groups', '{"Typhidot IgM Antibody", "Salmonella typhi O (TO)", "Salmonella typhi H (TH)", "Salmonella paratyphi AH", "Salmonella paratyphi BH"}', FALSE, FALSE),
('t-08', 'LFT001', 'Liver Function Test (LFT) Comprehensive Profile', 'Liver & Kidney', 'Serum', TRUE, 8, 8, 750, 499, 'Measures 11 vital liver enzymes, protein synthesis, and bilirubin fractions.', 'Assesses liver toxicity from medications, fatty liver (NAFLD), jaundice, and metabolic stress.', 'Alcohol Consumers, Fatty Liver, Digestion Issues', 'ALL', 'Adults 18+', '{"Bilirubin Total", "Bilirubin Direct (Conjugated)", "Bilirubin Indirect", "SGOT / AST", "SGPT / ALT", "Alkaline Phosphatase (ALP)", "Total Protein", "Serum Albumin", "Serum Globulin", "A:G Ratio", "Gamma GT (GGT)"}', TRUE, FALSE),
('t-09', 'KFT002', 'Kidney Function Test (KFT / RFT) with Electrolytes', 'Liver & Kidney', 'Serum', FALSE, 0, 8, 850, 549, 'Measures BUN, Creatinine, eGFR, Uric Acid, Calcium, and Sodium/Potassium/Chloride electrolytes.', 'Evaluates renal clearance, filtration capacity, electrolyte balance, and gout risk.', 'Hypertension, Diabetics, Swollen Feet, Proteinuria', 'ALL', 'Adults 18+', '{"Blood Urea Nitrogen (BUN)", "Serum Creatinine (Enzymatic)", "BUN / Creatinine Ratio", "eGFR (Estimated Glomerular Filtration)", "Uric Acid", "Serum Calcium", "Sodium (Na+)", "Potassium (K+)", "Chloride (Cl-)"}', TRUE, FALSE),
('t-10', 'SMG001', 'Smog & Air Pollution Lung Inflammation Panel', 'Allergy & Smog', 'Serum & EDTA Blood', FALSE, 0, 8, 1450, 899, 'Measures Total IgE, hs-CRP, and Absolute Eosinophil Count (AEC) to quantify toxic smog inflammation.', 'Assesses airway hyperreactivity, systemic vascular inflammation, and allergic asthma triggers from PM2.5/PM10.', 'Chronic Morning Cough, Throat Burning, Smog Wheezing', 'ALL', 'All Age Groups', '{"Total Serum IgE (Allergy Biomarker)", "High Sensitivity CRP (hs-CRP Cardiac & Vascular)", "Absolute Eosinophil Count (AEC)", "Total Leukocyte Count (TLC)", "Erythrocyte Sedimentation Rate (ESR)"}', TRUE, TRUE),
('t-11', 'VIT001', 'Vitamin B12 (Cyanocobalamin / Active B12)', 'Vitamins', 'Serum', FALSE, 0, 12, 900, 599, 'Quantifies active cyanocobalamin in blood for nerve myelin maintenance and red cell production.', 'Diagnoses megaloblastic anemia, diabetic peripheral neuropathy, and cognitive brain fog.', 'Vegetarians, Tingling Numbness, Nerve Weakness', 'ALL', 'All Age Groups', '{"Serum Vitamin B12 Concentration", "Biological Deficiency Status Interpretation"}', TRUE, FALSE),
('t-12', 'VIT002', 'Vitamin D 25-Hydroxy (Total D2 + D3)', 'Vitamins', 'Serum', FALSE, 0, 12, 1100, 699, 'Gold standard 25-OH Vitamin D immunoassay measuring bone density calcification and immunity status.', 'Pinpoints widespread bone pain, muscle spasms, osteopenia, and winter immunity vulnerability.', 'Bone Pain, Indoor Workers, Post-Menopausal Women', 'ALL', 'All Age Groups', '{"25-Hydroxy Vitamin D (Total D2 + D3)", "Insufficiency / Sufficiency Range Index"}', TRUE, FALSE)
