INSERT INTO health_packages (id, name, category, tagline, badge, total_tests, original_price, discount_price, sample_type, fasting_required, fasting_hours, turnaround_time, ideal_for, age_group, gender, highlights, description, is_winter_smog_focus, is_fever_focus) VALUES
('pkg-smog-01', 'North India Winter Smog & Respiratory Defense Profile', 'Specialized & Smog', 'Comprehensive Biomarker Screen for Toxic Air Pollution & Heavy Smog Exposure in Delhi NCR', 'Winter Smog Priority', 48, 3800, 1499, 'Blood & Serum', TRUE, 10, '12 Hours (Same Day)', 'Smog cough, breathlessness, eye irritation', 'All Adults in Delhi NCR & Punjab', 'ALL', '{"Total Serum IgE (Allergy Biomarker)", "High Sensitivity CRP (hs-CRP Inflammation)", "Complete Blood Count + Absolute Eosinophil Count", "Lipid Profile + Liver & Kidney Functional Status"}', 'Tailored specifically for North Indian urban residents enduring severe winter inversion smog and PM2.5 levels exceeding 400+ AQI.', TRUE, FALSE),
('pkg-fever-dengue-01', 'Aura North India Acute Fever & Dengue Care Package', 'Seasonal & Fever', 'Complete 38-Parameter Fever Differential: Dengue NS1, Platelets, Malaria, Typhoid & Vital Organs', 'Same-Day 4-Hour Express', 38, 3200, 1299, 'Blood, Serum & Urine', FALSE, 0, '4-6 Hours (STAT Express)', 'Acute High Fever, Chills, Body Ache, Low Platelets', 'Children & Adults with acute fever', 'ALL', '{"Dengue NS1 ELISA Antigen & IgM/IgG Duo", "Rapid 60-Minute Emergency Platelet Count", "Malaria Antigen Rapid (Pv / Pf)", "Typhoid Typhidot IgM & Widal Agglutination", "Liver Enzymes (SGPT / SGOT) & Urine Routine"}', 'Comprehensive multi-etiology acute fever differential designed to diagnose Dengue, Malaria, Typhoid, and systemic viral infections within 4 hours.', FALSE, TRUE),
('pkg-01', 'North India Comprehensive Full Body Checkup (Silver)', 'Full Body Screening', '64 Essential Biomarkers Covering Heart, Liver, Kidney, Blood, Thyroid, and Sugar', 'Most Popular', 64, 2999, 999, 'Blood, Serum, Fluoride Plasma, Urine', TRUE, 10, '12-16 Hours', 'Annual preventive health screening for individuals & families', 'Adults 20-55 Yrs', 'ALL', '{"Complete Hemogram (28 parameters)", "Lipid Profile (8 parameters)", "Liver Function Profile (11 parameters)", "Kidney Function Profile (9 parameters)", "Thyroid Profile Total (T3, T4, TSH)", "Fasting Blood Sugar (FBS)", "Urine Routine Examination"}', 'Standard preventive diagnostic package testing major body organs and metabolic indicators with multi-lab price comparison.', FALSE, FALSE),
('pkg-02', 'Aura North India Senior Citizen Platinum Wellness', 'Senior Citizen Care', '84 Advanced Parameters with Arthritis, Cardiac hs-CRP, Bone Minerals, and Nerve Vitamins', 'Senior Special', 84, 5800, 2199, 'Blood, Serum, Plasma, Urine', TRUE, 10, '16-24 Hours', 'Senior citizens (50+) with joint stiffness, hypertension, or diabetes history', 'Seniors 50+ Yrs', 'ALL', '{"All 64 Silver Full Body Tests", "Vitamin D3 (25-OH) & Vitamin B12", "High Sensitivity CRP (hs-CRP)", "Serum Calcium & Uric Acid", "Glycated Hemoglobin (HbA1c)", "Iron Deficiency Profile with Ferritin"}', 'Advanced geriatric health panel targeting age-related cardiovascular risk, osteoarthritis inflammation, bone density minerals, and diabetic neuropathy.', FALSE, FALSE)
INSERT INTO doctors (id, name, specialty, qualifications, experience_years, institution, city, rating, review_count, avatar, consultation_fee, is_free_report_review_available, available_modes, available_slots_today, languages, about, specialized_conditions, nmc_registration_number) VALUES
('doc-01', 'Dr. Sunita Aggarwal', 'Pathologist & Lab Report Consultant', 'MBBS, MD (Pathology, AIIMS New Delhi)', 18, 'AIIMS New Delhi Alumnus · National Lab Director', 'New Delhi & NCR', 4.9, 1420, 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop&q=80', 0, TRUE, '{VIDEO, IN_CLINIC}', '{"05:00 PM", "05:30 PM", "06:00 PM", "06:30 PM", "07:00 PM"}', '{English, Hindi, Punjabi}', 'Dr. Sunita Aggarwal is a senior pathologist with over 18 years of clinical laboratory expertise. She specializes in deep pathological interpretation of CBC, out-of-range liver/kidney biomarkers, thyroid anomalies, and lipid metabolic profiles.', '{"Lab Report Interpretation", "Anemia Differential Diagnosis", "Liver Enzyme Abnormalities", "Thyroid Lab Clarifications", "Fasting Blood Sugar Trends"}', 'NMC-DL-38491'),
('doc-02', 'Dr. Rajeshwar Varma', 'Pulmonologist (Chest & Smog)', 'MBBS, MD (Pulmonary Medicine, PGIMER Chandigarh), FCCP', 22, 'PGIMER Chandigarh Alumnus · Max Super Speciality Hospital', 'Gurugram (Gurgaon)', 4.9, 2180, 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=400&auto=format&fit=crop&q=80', 499, FALSE, '{VIDEO, IN_CLINIC}', '{"06:00 PM", "06:30 PM", "07:00 PM", "07:30 PM", "08:00 PM"}', '{English, Hindi, Punjabi}', 'Dr. Rajeshwar Varma is one of North India’s leading chest physicians, with extensive clinical practice managing pollution-induced respiratory distress, chronic winter cough, asthma exacerbations, and post-viral lung rehabilitation.', '{"Winter Smog Cough", "Asthma & Bronchitis", "Allergic Airway Rhinitis", "COPD Management", "Chest X-Ray & IgE Interpretation"}', 'NMC-HR-82910'),
('doc-03', 'Dr. Priya Nambiar', 'Diabetologist & Endocrinologist', 'MBBS, MD (Medicine), DM (Endocrinology, AIIMS New Delhi)', 14, 'Medanta The Medicity, Gurugram', 'Gurugram (Gurgaon)', 4.8, 980, 'https://images.unsplash.com/photo-1594824813596-749419131976?w=400&auto=format&fit=crop&q=80', 599, FALSE, '{VIDEO, IN_CLINIC}', '{"04:30 PM", "05:00 PM", "05:30 PM", "06:00 PM"}', '{English, Hindi}', 'Dr. Priya Nambiar provides comprehensive care for Type 1 & Type 2 Diabetes, Gestational Diabetes, Hashimoto’s Thyroiditis, and insulin resistance syndromes.', '{"Diabetes Mellitus Management", "HbA1c Target Planning", "Thyroid Disorders (Hypo/Hyper)", "PCOS / Insulin Resistance", "Metabolic Weight Management"}', 'NMC-DL-51209'),
('doc-04', 'Dr. Harmeet Singh Chadha', 'Cardiologist', 'MBBS, MD, DM (Cardiology, PGIMER Chandigarh)', 20, 'Fortis Memorial Research Institute (FMRI), Gurugram', 'Chandigarh (Tricity)', 4.9, 1640, 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?w=400&auto=format&fit=crop&q=80', 699, FALSE, '{VIDEO, IN_CLINIC}', '{"05:00 PM", "05:45 PM", "06:30 PM", "07:15 PM"}', '{English, Hindi, Punjabi}', 'Dr. Harmeet Singh Chadha specializes in preventative cardiology, lipid management, hypertension control, and early coronary artery disease screening.', '{"High Cholesterol & Lipid Control", "Hypertension & BP Fluctuations", "Post-Angioplasty Follow-up", "Preventive Cardiac Screenings", "ECG & Echo Report Reviews"}', 'NMC-PB-29401'),
('doc-05', 'Dr. Shalini Kapoor', 'Gynecologist & Obstetrician', 'MBBS, MS (Obstetrics & Gynaecology, Safdarjung Hospital Delhi)', 16, 'Apollo Cradle / Max Healthcare', 'Noida & Greater Noida', 4.8, 1120, 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop&q=80', 499, FALSE, '{VIDEO, IN_CLINIC}', '{"04:00 PM", "04:30 PM", "05:00 PM", "05:30 PM"}', '{English, Hindi}', 'Dr. Shalini Kapoor specializes in adolescent and adult women’s health, PCOD/PCOS hormonal balance, prenatal diagnostic reviews, and preconception wellness.', '{"PCOD & Menstrual Irregularities", "Hormonal Imbalance Reviews", "Preconception Health Checkup", "Pelvic Ultrasound Report Analysis", "Menopausal Health Care"}', 'NMC-UP-44912'),
('doc-06', 'Dr. Amitav Mukhopadhyay', 'General Physician & Family Medicine', 'MBBS, MD (Internal Medicine, UCMS & GTB Hospital Delhi)', 12, 'Sir Ganga Ram Hospital Clinical Associate', 'New Delhi & NCR', 4.7, 850, 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=400&auto=format&fit=crop&q=80', 299, FALSE, '{VIDEO, IN_CLINIC}', '{"03:00 PM", "03:30 PM", "04:00 PM", "04:30 PM", "05:00 PM"}', '{English, Hindi, Bengali}', 'Dr. Amitav Mukhopadhyay is an empathetic family medicine practitioner experienced in seasonal fever management, viral gastroenteritis, blood pressure optimization, and routine preventive wellness counseling.', '{"Seasonal Viral Fever & Dengue Recovery", "Fatigue & Vitamin Deficiencies", "Gastritis & Acid Reflux", "Routine Health Checkup Counseling", "Preventive Immunization Advice"}', 'NMC-DL-67210')
